    {
        var outcome = await gateway.AuthorizeAsync(reference, amount, cancellationToken);
        await receipts.SaveAsync(reference, $"{amount.Currency} {amount.Amount} -> {outcome}", cancellationToken);
        return outcome;
    }
}
