using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(IPaymentGateway).Assembly;
    private static readonly Assembly Infrastructure = typeof(FileSystemReceiptStore).Assembly;

    // Technical details that business code must reach only through its own abstractions.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO",
        "System.Net",
        "System.Data",
        "System.Text.Json",
        "Microsoft.Data",
        "Microsoft.EntityFrameworkCore",
    ];

    [Fact]
    public void Domain_does_not_depend_on_the_other_layers()
    {
        AssertNoDependency(Domain, "PaymentAuthorization.Application", "PaymentAuthorization.Infrastructure");
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        AssertNoDependency(Application, "PaymentAuthorization.Infrastructure");
    }

    [Fact]
    public void Domain_does_not_use_technical_details()
    {
        AssertNoDependency(Domain, TechnicalNamespaces);
    }

    [Fact]
    public void Application_does_not_use_technical_details()
    {
        AssertNoDependency(Application, TechnicalNamespaces);
    }

    private static void AssertNoDependency(Assembly layer, params string[] forbidden)
    {
        var result = Types.InAssembly(layer).That().AreNotNested().ShouldNot().HaveDependencyOnAny(forbidden).GetResult();

        Assert.True(result.IsSuccessful,
            $"Forbidden dependency in: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }
}
